<?php
declare(strict_types=1);
function shortDirectoryCategory(string $code,string $label,string $locale): string {
    $labels=[
      'Hospedaje'=>['Hospedaje','Stays','Hospedagem'],
      'Alimentación'=>['Comida','Food','Comida'],
      'Venta de licores'=>['Licores','Liquor','Bebidas'],
      'Bares, discotecas y vida nocturna'=>['Vida nocturna','Nightlife','Vida noturna'],
      'Supermercados, tiendas y comercio'=>['Compras','Shopping','Compras'],
      'Farmacia y salud'=>['Salud','Health','Saúde'],
      'Experiencias y actividades'=>['Actividades','Activities','Atividades'],
      'Cultura y entretenimiento'=>['Cultura','Culture','Cultura'],
      'Transporte'=>['Transporte','Transport','Transporte'],
      'Servicios locales'=>['Servicios','Services','Serviços']
    ];
    $index=$locale==='en'?1:($locale==='pt-BR'?2:0);
    foreach($labels as $long=>$values)if($label===$long||in_array($label,$values,true))return $values[$index];
    $codes=['hospedaje'=>'Hospedaje','alimentacion'=>'Alimentación','licores'=>'Venta de licores','vida-nocturna'=>'Bares, discotecas y vida nocturna','comercio'=>'Supermercados, tiendas y comercio','salud'=>'Farmacia y salud','experiencias'=>'Experiencias y actividades','cultura'=>'Cultura y entretenimiento','transporte'=>'Transporte','servicios'=>'Servicios locales'];
    return isset($codes[$code])?$labels[$codes[$code]][$index]:$label;
}

